import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { MareaI18n } from '../../core/i18n';
import { MareaLink } from '../foundation/marea-link';

export interface MareaBreadcrumbItem {
  readonly label: string;
  readonly href?: string | null;
}

/**
 * Breadcrumb navigation.
 *
 * Native `<nav>`/`<ol>`/`<li>` structure. The last item is the current page and
 * is not a link; other items with an `href` render a quiet link. Separators are
 * generated by CSS (never announced, never an icon-only control).
 */
@Component({
  selector: 'marea-breadcrumb',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [MareaLink],
  host: { 'data-marea-component': 'marea-breadcrumb' },
  template: `
    <nav class="nav" [attr.aria-label]="ariaLabel()">
      <ol class="list">
        @for (item of items(); track $index; let last = $last) {
          <li class="item">
            @if (last) {
              <span class="current" aria-current="page">{{ item.label }}</span>
            } @else if (item.href) {
              <a marea-link variant="quiet" [href]="item.href">{{ item.label }}</a>
            } @else {
              <span class="label">{{ item.label }}</span>
            }
          </li>
        }
      </ol>
    </nav>
  `,
  styles: `
    :host {
      display: block;
      min-inline-size: 0;
    }
    .list {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      margin: 0;
      padding: 0;
      list-style: none;
      font-family: var(--marea-font-body);
      font-size: var(--marea-type-body-small-size);
      line-height: var(--marea-type-body-small-line-height);
    }
    .item {
      display: inline-flex;
      align-items: center;
      min-block-size: var(--marea-touch-target-min);
      min-inline-size: 0;
    }
    .item a {
      min-block-size: var(--marea-touch-target-min);
    }
    .item + .item::before {
      content: '/';
      display: inline-block;
      margin-inline: var(--marea-space-1);
      color: var(--marea-text-meta);
    }
    .current {
      color: var(--marea-text-primary);
      font-weight: 600;
      overflow-wrap: anywhere;
    }
    .label {
      color: var(--marea-text-secondary);
      overflow-wrap: anywhere;
    }
  `,
})
export class MareaBreadcrumb {
  readonly label = input<string>('');
  readonly items = input.required<readonly MareaBreadcrumbItem[]>();

  readonly i18n = inject(MareaI18n);

  readonly ariaLabel = computed(() => this.label() || this.i18n.text('breadcrumb'));
}
